// Extract structured report data from webhook payload
const body = $json.body || $json;

const employeeName = body.employeeName || body.author_name || 'Employee';
const date = body.date || new Date().toISOString().split('T')[0];
const completed = (body.completed || '- None').trim();
const pending = (body.pending || '- None').trim();
const issues = (body.issues || 'None').trim();
const tomorrow = (body.tomorrow || '- None').trim();
const recipientPhone = body.recipientPhone || '917358859792';
const recipientName = body.recipientName || 'Manager';

// Format WhatsApp Message matching exact layout
const formattedMessage = `Daily Report\n\n` +
  `Employee: ${employeeName}\n` +
  `Date: ${date}\n\n` +
  `Completed:\n${completed}\n\n` +
  `Pending:\n${pending}\n\n` +
  `Issues:\n${issues}\n\n` +
  `Tomorrow:\n${tomorrow}`;

return {
  employeeName,
  date,
  completed,
  pending,
  issues,
  tomorrow,
  recipientPhone,
  recipientName,
  formattedMessage
};

